import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.C8xYrcAN.js";const h=JSON.parse('{"title":"Privacy Policy","description":"Chaldea privacy policy covering personal information, permissions, third-party services, retention and your rights.","frontmatter":{"title":"Privacy Policy","description":"Chaldea privacy policy covering personal information, permissions, third-party services, retention and your rights.","lastUpdated":false,"editLink":false},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md"}'),i={name:"guide/privacy.md"};function r(s,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><strong>Version: v1 · Effective date: October 25, 2026</strong></p><p>This policy explains how the Chaldea service provider, <strong>Zhixing Yuanjing (Taizhou) Technology Co., Ltd.</strong> (“we” or “us”), processes personal information when providing the Chaldea App and related services, and how you can manage your information.</p><p>For privacy matters, see <a href="./contact#privacy-contact">Contact Us</a>. We will <strong>respond within 15 working days</strong> after receiving a privacy complaint or rights request.</p><h2 id="_1-basic-features-and-optional-services" tabindex="-1">1. Basic features and optional services <a class="header-anchor" href="#_1-basic-features-and-optional-services" aria-label="Permalink to &quot;1. Basic features and optional services&quot;">​</a></h2><p>Chaldea provides game reference information, material planning, team building and battle simulation. Basic local features do not require an account, your real name, phone number or identity document. Servers receiving requests for game data, images or updates receive your IP address and necessary request information.</p><p>Accounts, cloud recovery, online team publishing, GitHub backups, product analytics, diagnostics and advertising serve specific purposes. Refusing unnecessary processing should not prevent use of unrelated basic features. System permissions, personalized advertising preferences and privacy consent are separate choices and do not replace one another.</p><h2 id="information-and-purposes" tabindex="-1">2. Information and purposes <a class="header-anchor" href="#information-and-purposes" aria-label="Permalink to &quot;2. Information and purposes {#information-and-purposes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Information</th><th>Purpose and trigger</th></tr></thead><tbody><tr><td>Local planning, simulation and data management</td><td>Game progress, plans, teams and preferences you enter</td><td>Stored and processed on your device; relevant content may leave it when you back up, share or submit feedback</td></tr><tr><td>Account registration, login and maintenance</td><td>Username, email, password verification information, sessions and device identifiers; request IP, App version, platform and language</td><td>Accounts, email verification, changes, password reset, assisted recovery and security. The server stores password hashes for verification</td></tr><tr><td>Cloud recovery copies</td><td>Account association, user data files you upload, upload time</td><td>Temporary recovery or transfer between devices. This is not permanent storage; keep your own local backup</td></tr><tr><td>Online teams</td><td>Submitted teams, descriptions, author/account association, votes and activity records</td><td>Publishing, browsing, maintenance and moderation. Published content is visible to others; do not include unrelated personal information</td></tr><tr><td>Local backup and file import/export</td><td>Backup and JSON/CSV files you choose, exported content</td><td>Your file picker or share action; selecting a file does not authorize access to every file on your device</td></tr><tr><td>Clipboard import</td><td>Text, data or team links you actively paste or import</td><td>Parsing that import, rather than continuous clipboard collection</td></tr><tr><td>Saving, copying and sharing images</td><td>Selected images and generated plan/team images</td><td>Saving to photos or the clipboard, or sending to an app you choose; the receiving app has its own policy</td></tr><tr><td>Updates and APK/XAPK downloads/installation</td><td>Version, platform/channel, download requests and packages</td><td>Checking or obtaining updates and downloading game packages; methods and installation authorization vary by platform/channel</td></tr><tr><td>Feedback you submit</td><td>Message, contact details you supply, diagnostic logs, device/App parameters and attached data files or other materials</td><td>Responding and troubleshooting after your submission. Review your feedback and avoid passwords, Tokens and unrelated personal information</td></tr><tr><td>Automatic diagnostics (optional)</td><td>Technical logs, stack traces, device and App parameters</td><td>With your permission, troubleshooting using automatic reports that exclude screenshots, complete user files and settings snapshots</td></tr><tr><td>Product analytics (optional, Android/iOS)</td><td>SDK device identifier, device/system and App parameters, IP, sessions, views/events, language, preferred game regions and channel</td><td>Our Countly service measures feature use and stability. Identifiers can link records; this data is not described as fully anonymous</td></tr><tr><td>Advertising (versions/channels where enabled)</td><td>Device, network, identifier and ad interaction information described in the <a href="./third-party-sdks">Third-party SDK List</a></td><td>Delivery, measurement, attribution and fraud prevention; personalization also depends on your preference and system authorization</td></tr></tbody></table><p><strong>Automatic diagnostics and feedback have different scopes.</strong> Disabling automatic diagnostics does not block feedback you choose to submit. Automatic diagnostics run only with your consent and when you enable the option.</p><h2 id="system-permissions" tabindex="-1">3. System permissions and device capabilities <a class="header-anchor" href="#system-permissions" aria-label="Permalink to &quot;3. System permissions and device capabilities {#system-permissions}&quot;">​</a></h2><p>Capabilities are used for the corresponding functions. You can review or change available permissions in the system settings for Chaldea. Available controls vary by system, version and channel. Refusing a permission affects its associated operation and should not affect unrelated local features.</p><table tabindex="0"><thead><tr><th>Permission/capability</th><th>Platform and use</th></tr></thead><tbody><tr><td>Internet, network state and Wi-Fi state</td><td>Requests for data, images, accounts, updates and enabled services. Ordinary Android network permissions generally have no runtime permission prompt</td></tr><tr><td>Adding photos/saving images</td><td>iOS saves images you choose and requests add-only authorization when needed; saving images does not require access to read the entire photo library</td></tr><tr><td>Legacy storage</td><td>Android packages declare READ_EXTERNAL_STORAGE (maximum SDK 32) and WRITE_EXTERNAL_STORAGE (maximum SDK 28). Legacy saving/file compatibility may require authorization. System file pickers grant access to selected content</td></tr><tr><td>Installing unknown apps</td><td>Android GitHub/F-Droid builds may direct you to system settings when you choose to install APK/XAPK files. The Google Play package does not declare REQUEST_INSTALL_PACKAGES</td></tr><tr><td>Phone state</td><td>Android packages retain READ_PHONE_STATE. An advertising SDK may use phone-state information for device identification/fraud prevention within system limits. It is not necessary for basic local features and does not authorize reading call contents</td></tr><tr><td>Advertising identifiers and tracking</td><td>Android ad ID availability depends on the system/settings. iOS IDFA tracking requires the system ATT decision. Refusal or withdrawal must not be bypassed with replacement identifiers</td></tr></tbody></table><p>Package declarations, actual requests and granted authorization are different. Internal SDK signature permissions support component communication and are not personal-information switches you need to enable. Residual declarations for unavailable features are not a justification for collecting information.</p><h2 id="third-party-sdks" tabindex="-1">4. SDKs and external services you choose <a class="header-anchor" href="#third-party-sdks" aria-label="Permalink to &quot;4. SDKs and external services you choose {#third-party-sdks}&quot;">​</a></h2><p>We use SDKs for advertising, optional analytics and web content display. See the <a href="./third-party-sdks">Third-party SDK List</a> for component names, providers, versions, information processed and applicability. The list forms part of this Privacy Policy and shares its version and effective date.</p><p>When you configure a GitHub Token, repository and path for backup/restore, the credentials and backup content are used for requests to GitHub. Use a minimally scoped Token and check repository visibility; a public repository may expose backup content. GitHub&#39;s independent processing and storage are covered by its <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">Privacy Statement</a>.</p><p>Opening external reference, video, documentation, community or donation links sends requests to the relevant service, which has its own policy. System sharing sends content to your chosen recipient app.</p><h2 id="_5-managing-ads-and-optional-processing" tabindex="-1">5. Managing ads and optional processing <a class="header-anchor" href="#_5-managing-ads-and-optional-processing" aria-label="Permalink to &quot;5. Managing ads and optional processing&quot;">​</a></h2><p>In Settings → Privacy &amp; Data, you can manage personalized ads, automatic crash diagnostics and product analytics preferences. Advertising settings provide the options available in your version. The initial personalized-ad preference is on; this does not grant system permissions or replace legally required consent. When personalization is off, an enabled advertising service should offer a non-personalized option; necessary ad-delivery network requests may remain.</p><p>iOS tracking also follows your ATT choice. Withdrawal does not invalidate earlier lawful processing; contact us under section 8 to request deletion of retained information. When you disable optional processing, we stop that processing. Withdrawing consent does not prevent you from submitting feedback.</p><h2 id="_6-storage-location-and-retention" tabindex="-1">6. Storage location and retention <a class="header-anchor" href="#_6-storage-location-and-retention" aria-label="Permalink to &quot;6. Storage location and retention&quot;">​</a></h2><p>Our own account and cloud recovery services are hosted in mainland China. GitHub, third-party websites and other independent services you choose may use infrastructure elsewhere; consider their policies when deciding whether to use them. This mainland China storage statement does not apply to independent third-party services you choose to use.</p><p>From this policy’s effective date, we retain personal information under the following rules. When a period ends, information should be deleted or irreversibly anonymized so individuals cannot be identified. Information subject to a legal retention requirement is retained only for that requirement.</p><table tabindex="0"><thead><tr><th>Information</th><th>Retention/deletion rule</th></tr></thead><tbody><tr><td>Local data and exported files</td><td>Until you overwrite or delete them; uninstall behavior also depends on system backups, external folders and copies you keep</td></tr><tr><td>Account and service records</td><td>While needed to provide the account; deleted/anonymized after closure or another deletion trigger, subject to necessary security/legal retention</td></tr><tr><td>Cloud recovery copies</td><td>Up to <strong>7 days from upload</strong>; replacement, deletion or account closure may remove them earlier</td></tr><tr><td>Automatic diagnostic reports</td><td><strong>90 days from receipt</strong></td></tr><tr><td>Feedback and attachments</td><td><strong>180 days from receipt</strong></td></tr><tr><td>Countly records linkable to individuals/devices</td><td><strong>90 days from recording</strong></td></tr><tr><td>Published teams</td><td>While you retain the publication or necessary service disputes are handled; you can delete your own posts, but we do not control copies others saved</td></tr><tr><td>Legally required network security logs</td><td>The applicable legal period; relevant network logs subject to China&#39;s Cybersecurity Law must be kept for at least <strong>six months</strong>. This is not a universal retention period for diagnostics/analytics</td></tr><tr><td>Disaster-recovery copies, feedback inbox/forwarded copies and website tools</td><td>Disaster-recovery, feedback inbox and forwarded copies under our control follow the retention period for the corresponding data; website analytics providers’ retention rules are described in the policies linked in section 9</td></tr></tbody></table><p>You and GitHub&#39;s settings control copies in GitHub. Independently retained third-party SDK data follows the relevant policy and law; we will assist with appropriate requests.</p><h2 id="_7-sharing-security-and-changes-of-purpose" tabindex="-1">7. Sharing, security and changes of purpose <a class="header-anchor" href="#_7-sharing-security-and-changes-of-purpose" aria-label="Permalink to &quot;7. Sharing, security and changes of purpose&quot;">​</a></h2><p>We use necessary technical, hosting and communication services for the services you choose. Basic feature use does not authorize arbitrary sharing. Processing on our behalf, disclosure to independent recipients, public posting and sharing you initiate have different meanings; we will meet the applicable notice, contractual and consent requirements for each arrangement.</p><p>Feedback and attachments are used to respond and troubleshoot, and may be processed through providers of email, communication or hosting services. Where a recipient or international transfer requires further notice, consent or another legally required procedure, we complete it before the processing begins. Where a new purpose, recipient or processing method requires further notice or consent, we will complete that process first.</p><p>We use access control, transport protection and account security appropriate to the service. Protect your passwords, Tokens, backups and shared content. We will handle and notify personal-information security incidents as required by law.</p><h2 id="operator-and-contact" tabindex="-1">8. Your rights and contact <a class="header-anchor" href="#operator-and-contact" aria-label="Permalink to &quot;8. Your rights and contact {#operator-and-contact}&quot;">​</a></h2><p>Chaldea and related services are provided by <strong>Zhixing Yuanjing (Taizhou) Technology Co., Ltd.</strong> You can modify available account information, delete your online content, manage optional processing/system permissions and request account closure through the account deletion entry. Closing an account does not automatically delete exported files, GitHub copies or content retained by recipients.</p><p>To request access, a copy, correction, completion or deletion of information, withdraw consent, close an account or object to processing, use the channels in <a href="./contact#privacy-contact">Contact Us</a>. We will request only information necessary to verify the request, not complete passwords or Tokens. We will <strong>respond within 15 working days</strong>, explaining the reason and available next steps if we cannot fulfill a request directly. You may also complain to the competent authority under applicable law.</p><h2 id="_9-documentation-website" tabindex="-1">9. Documentation website <a class="header-anchor" href="#_9-documentation-website" aria-label="Permalink to &quot;9. Documentation website&quot;">​</a></h2><p>The documentation website uses <strong>Google Analytics</strong> and <strong>Baidu Analytics</strong> to understand visits. These tools may process cookies, IP addresses, device/browser information and page visits. See <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google&#39;s policy</a> and <a href="https://tongji.baidu.com/web/help/article?id=330&amp;type=0" target="_blank" rel="noreferrer">Baidu Analytics&#39; policy</a> for their processing practices. Website analytics and Countly inside the App are separate processing activities.</p><h2 id="_10-policy-changes" tabindex="-1">10. Policy changes <a class="header-anchor" href="#_10-policy-changes" aria-label="Permalink to &quot;10. Policy changes&quot;">​</a></h2><p>The policy version and effective date are stated at the top of this page. Material changes will be notified through the policy page and necessary App notices. Where renewed consent is legally required, continued use does not automatically replace it.</p>',37)])])}const y=t(i,[["render",r]]);export{h as __pageData,y as default};
